	if m.ClusterID != clusterID {
		return false
	}
	if m.ClientID == NotSessionManagedClientID {
		return false
	}
	if m.SeriesID == SeriesIDForRegister ||
		m.SeriesID == SeriesIDForUnregister {
		return false
	}
	if m.RespondedTo > m.SeriesID {
		panic("m.RespondedTo > m.SeriesID")
	}
